window.LECTURE = {"p1": [{"n": 1, "title": "Chapter 11: Automated Planning", "sec": "Introduction", "dur": 34222, "clicks": [], "segs": [{"click": 0, "sents": [[500, "Welcome to Chapter 11, Automated Planning."], [3522, "In this chapter we ask how an intelligent agent decides what to do, and how it can prove, before it acts, that its plan will work."], [12876, "We'll follow two worlds the whole way through: the textbook's Air Cargo problem, with planes, airports, and cargo, and our own Northgate General Hospital, with Maria Santos, Dr. Okafor, and Nurse Priya."], [27410, "The chapter has seven sections, shown at the bottom of the screen."], [32159, "Let's begin."]]}]}, {"n": 2, "title": "Why Planning, and Why Now?", "sec": "Introduction", "dur": 77611, "clicks": [5726, 21995, 39622, 50197, 61894], "segs": [{"click": 0, "sents": [[500, "Before we define anything, let's ask why we need planning at all."]]}, {"click": 1, "sents": [[5876, "Think back to Chapter 3."], [7473, "A search agent can be very smart, but for every new problem, a human has to sit down and write its heuristic."], [14725, "Manhattan distance for the eight-puzzle, straight-line distance for route finding."], [20181, "That doesn't scale."]]}, {"click": 2, "sents": [[22145, "Now think back to Chapter 7."], [24215, "A logical agent needed the same rule written again and again: once for every time step, every square, every direction."], [32937, "In the wumpus world, the move-forward rule alone exploded into thousands of copies."]]}, {"click": 3, "sents": [[39772, "Planning fixes the first problem with action schemas."], [43564, "One template, with variables, stands in for every specific action in every situation."]]}, {"click": 4, "sents": [[50347, "And it fixes the second with factored states."], [53365, "Because a state is broken into named facts, the computer can work out good heuristics on its own, with no human needed."]]}, {"click": 5, "sents": [[62044, "These aren't toy ideas."], [63664, "NASA's Remote Agent used them to command the Deep Space One spacecraft in 1999, and Hitachi used a hierarchical planner to schedule a factory line with over two thousand operations."]]}]}, {"n": 3, "title": "Two Domains, One Toolkit", "sec": "Introduction", "dur": 57816, "clicks": [5256, 18782, 37611, 50588], "segs": [{"click": 0, "sents": [[500, "We'll use two running examples in this chapter, side by side."]]}, {"click": 1, "sents": [[5406, "The first is the textbook's Air Cargo problem: two pieces of cargo, two planes, and two airports, San Francisco and New York's JFK."], [15118, "We'll use it to introduce every core idea."]]}, {"click": 2, "sents": [[18932, "The second is a hospital you already know from Chapter 10: Northgate General."], [24975, "Same cast: Maria Santos, Dr. Okafor, Nurse Priya, and Operating Room 3."], [30547, "Last chapter we asked what they know."], [33451, "This chapter we ask: what should they do next?"]]}, {"click": 3, "sents": [[37761, "Here's why we use both."], [39375, "A domain-independent planner runs exactly the same code whether it's moving cargo or moving a patient toward recovery."], [47654, "Only the objects and names change."]]}, {"click": 4, "sents": [[50738, "So each time we learn something with Air Cargo, we'll check that it carries over to Northgate."]]}]}, {"n": 4, "title": "Chapter 11 in Seven Sections", "sec": "Introduction", "dur": 65673, "clicks": [9096, 18390, 29852, 43222, 55964], "segs": [{"click": 0, "sents": [[500, "Here's the map for this chapter."], [2646, "Seven sections, which group into three big ideas, then two extensions to the real world."]]}, {"click": 1, "sents": [[9246, "Section 11.1 is representation: how to write a planning problem down, in a language called PDDL."]]}, {"click": 2, "sents": [[18540, "Section 11.2 is search: once the problem is written down, we can search forward from the start, backward from the goal, or turn it into logic."]]}, {"click": 3, "sents": [[30002, "Sections 11.3 and 11.4 are structure: heuristics that the computer works out itself, and hierarchy, which lets us plan at a high level before filling in details."]]}, {"click": 4, "sents": [[43372, "Sections 11.5 and 11.6 take planning into the real world: what to do when you can't see everything, and how to add time and limited resources."]]}, {"click": 5, "sents": [[56114, "And section 11.7 closes the loop: why planning is hard in theory, and why it works so well in practice anyway."]]}]}, {"n": 5, "title": "11.1 Defining Classical Planning", "sec": "11.1 Defining Classical Planning", "dur": 24531, "clicks": [], "segs": [{"click": 0, "sents": [[500, "Section 11.1: Defining Classical Planning."], [3853, "Before a computer can plan, someone has to write the problem down precisely: where we start, what actions are allowed, and what must become true."], [15428, "This section introduces the language for that, called PDDL, and works through four example domains."]]}]}, {"n": 6, "title": "The Planning Question", "sec": "11.1 Defining Classical Planning", "dur": 65334, "clicks": [9252, 24633, 35129, 47062, 52594], "segs": [{"click": 0, "sents": [[500, "Every planning problem asks the same question: given where I am now, what sequence of actions gets me to my goal?"]]}, {"click": 1, "sents": [[9402, "Planning is different from just acting."], [12041, "The agent works out the whole sequence before it starts, and the result is something we can check: a list of legal actions, not a vague intention like get to the airport somehow."]]}, {"click": 2, "sents": [[24783, "Classical planning makes four simplifying assumptions."], [29015, "First, discrete: the world changes in distinct steps, not continuously."]]}, {"click": 3, "sents": [[35279, "Second, deterministic: every action has exactly one predictable result."], [42337, "Fly a plane to JFK, and it arrives at JFK."]]}, {"click": 4, "sents": [[47212, "Third, static: nothing changes while the agent is thinking."]]}, {"click": 5, "sents": [[52744, "And fourth, fully observable: the agent can see every fact that matters."], [58773, "In section 11.5, we'll break the last two, and see what changes."]]}]}, {"n": 7, "title": "PDDL: A Language for Planning", "sec": "11.1 Defining Classical Planning", "dur": 57967, "clicks": [8129, 19017, 26065, 32486, 47135], "segs": [{"click": 0, "sents": [[500, "To plan, we need a language for describing problems."], [5281, "The standard one is PDDL."]]}, {"click": 1, "sents": [[8279, "PDDL stands for Planning Domain Definition Language."], [12586, "Its big idea is that one schema can describe a whole family of actions."]]}, {"click": 2, "sents": [[19167, "Compare where we've been."], [20930, "With atomic search, a person writes a heuristic for every domain."]]}, {"click": 3, "sents": [[26215, "With propositional logic, we write an axiom for every object and every time step."]]}, {"click": 4, "sents": [[32636, "With PDDL, one schema works for any number of objects."], [37093, "Fly any plane between any two airports is a single schema, not one rule per plane, per airport pair, per time step."]]}, {"click": 5, "sents": [[47285, "Real PDDL files use a Lisp-like syntax, but we'll write it the way the textbook does, in the logic notation you already know."]]}]}, {"n": 8, "title": "The Planning Problem: Init, Actions, Goal", "sec": "11.1 Defining Classical Planning", "dur": 56635, "clicks": [6039, 12303, 16556, 26425, 40448], "segs": [{"click": 0, "sents": [[500, "Formally, every classical planning problem has just three ingredients."]]}, {"click": 1, "sents": [[6189, "Init describes where the agent starts: the facts that are true at the beginning."]]}, {"click": 2, "sents": [[12453, "Actions describe what the agent is allowed to do."]]}, {"click": 3, "sents": [[16706, "And the goal describes what must become true."], [19832, "Notice the goal doesn't have to describe the whole world, only the facts we care about."]]}, {"click": 4, "sents": [[26575, "Here's a tiny example."], [28746, "Plane P1 starts at San Francisco."], [32002, "The plan is one action: fly P1 from San Francisco to JFK."], [37627, "The goal: P1 is at JFK."]]}, {"click": 5, "sents": [[40598, "To test the plan, we apply the action to the starting state."], [45517, "P1 ends up at JFK."], [46992, "Is every goal fact in the result?"], [49698, "Yes."], [50025, "The plan works."], [51255, "That's the literal, mechanical test a planner runs."]]}]}, {"n": 9, "title": "States and the Closed-World Assumption", "sec": "11.1 Defining Classical Planning", "dur": 47837, "clicks": [4054, 16875, 23061, 34288], "segs": [{"click": 0, "sents": [[500, "Next: what exactly is a state?"]]}, {"click": 1, "sents": [[4204, "A state is simply the set of facts that are true right now."], [9240, "Cargo C1 is at San Francisco, cargo C2 is at JFK, and plane P1 is at San Francisco."]]}, {"click": 2, "sents": [[17025, "Now ask: is P1 at JFK?"], [19439, "That fact isn't in the list."]]}, {"click": 3, "sents": [[23211, "Under the closed-world assumption, a fact that isn't listed is false."], [29527, "So P1 is not at JFK."], [31358, "The hook symbol means not."]]}, {"click": 4, "sents": [[34438, "This keeps states short."], [36245, "We only write what's true."], [38203, "It works like a database, where a missing row means no."], [42345, "Remember this, because section 11.5 will have to drop it."]]}]}, {"n": 10, "title": "Action Schemas", "sec": "11.1 Defining Classical Planning", "dur": 63035, "clicks": [5883, 16953, 28494, 35881, 47579], "segs": [{"click": 0, "sents": [[500, "Actions are written as schemas."], [2956, "Think of a schema as a recipe."]]}, {"click": 1, "sents": [[6033, "Every schema has a name, with variables."], [10223, "Here: Load, c, p, a."], [12318, "Load cargo c into plane p at airport a."]]}, {"click": 2, "sents": [[17103, "The precondition says what must be true first: the cargo is at the airport, and the plane is at the same airport."], [25853, "The wedge symbol means and."]]}, {"click": 3, "sents": [[28644, "The effect says what changes: the cargo is no longer at the airport, and it's now in the plane."]]}, {"click": 4, "sents": [[36031, "To get a real action, we substitute real objects for the variables: c becomes C1, p becomes P1, a becomes San Francisco."]]}, {"click": 5, "sents": [[47729, "Every c becomes C1, everywhere."], [50316, "The result is one concrete action: load C1 into P1 at San Francisco."], [55992, "That substitution is called grounding, and it's completely mechanical."]]}]}, {"n": 11, "title": "The RESULT Rule", "sec": "11.1 Defining Classical Planning", "dur": 65015, "clicks": [5491, 15020, 27110, 37841, 44418, 52746], "segs": [{"click": 0, "sents": [[500, "Now the engine of all classical planning: the RESULT rule."]]}, {"click": 1, "sents": [[5641, "Read it as: the new state equals the old state, minus whatever the action deletes, plus whatever the action adds."]]}, {"click": 2, "sents": [[15170, "Let's try it."], [16516, "The state: P1 is at San Francisco, and C2 is at JFK."], [21900, "The action: fly P1 from San Francisco to JFK."]]}, {"click": 3, "sents": [[27260, "The delete list is the negative part of the effect: P1 at San Francisco."], [33433, "The add list is the positive part: P1 at JFK."]]}, {"click": 4, "sents": [[37991, "First, remove the deleted fact."], [41365, "Only C2 at JFK is left."]]}, {"click": 5, "sents": [[44568, "Then add the new fact."], [47150, "The result: C2 is at JFK, and P1 is at JFK."]]}, {"click": 6, "sents": [[52896, "Notice C2 at JFK was never touched."], [55791, "Facts the action doesn't mention just ride along unchanged."], [60672, "That's what keeps planning manageable."]]}]}, {"n": 12, "title": "Air Cargo: The Problem", "sec": "11.1 Defining Classical Planning", "dur": 49483, "clicks": [5883, 24450, 31759, 39695], "segs": [{"click": 0, "sents": [[500, "Now let's write a full problem: the textbook's Air Cargo domain."]]}, {"click": 1, "sents": [[6033, "We have two pieces of cargo, C1 and C2, two planes, P1 and P2, and two airports, San Francisco and JFK."], [16796, "C1 and plane P1 start at San Francisco."], [20871, "C2 and plane P2 start at JFK."]]}, {"click": 2, "sents": [[24600, "Here's the initial state in PDDL."], [27807, "Each fact says where one object is."]]}, {"click": 3, "sents": [[31909, "And the goal: C1 at JFK, and C2 at San Francisco."], [36637, "We want to swap the cargo."]]}, {"click": 4, "sents": [[39845, "Notice the goal says nothing about the planes."], [42831, "Any plan that gets the cargo right counts as a solution, wherever the planes end up."]]}]}, {"n": 13, "title": "Air Cargo: Load, Fly, Unload", "sec": "11.1 Defining Classical Planning", "dur": 46636, "clicks": [6118, 14628, 21937, 31963], "segs": [{"click": 0, "sents": [[500, "Air Cargo has three actions."], [2789, "Each one changes only a few facts."]]}, {"click": 1, "sents": [[6268, "Load: if the cargo and the plane are at the same airport, the cargo leaves the airport and goes into the plane."]]}, {"click": 2, "sents": [[14778, "Fly: if the plane is at the departure airport, it leaves there and arrives at the destination."]]}, {"click": 3, "sents": [[22087, "Unload: if the cargo is in the plane, and the plane is at an airport, the cargo is now at that airport and no longer in the plane."]]}, {"click": 4, "sents": [[32113, "Here's a subtle point."], [33697, "Once cargo is in a plane, it isn't at any airport."], [37298, "So when the plane flies, we don't have to update the cargo's location."], [42339, "It simply comes out wherever it's unloaded."]]}]}, {"n": 14, "title": "Air Cargo: The Plan, Step by Step", "sec": "11.1 Defining Classical Planning", "dur": 62168, "clicks": [5491, 17110, 28808, 41158, 49172, 52223], "segs": [{"click": 0, "sents": [[500, "Let's watch a planner solve Air Cargo, one step at a time."]]}, {"click": 1, "sents": [[5641, "Step one: load C1 into P1 at San Francisco."], [9833, "Both are at San Francisco, so the preconditions hold."], [15000, "Now C1 is in P1."]]}, {"click": 2, "sents": [[17260, "Step two: fly P1 to JFK."], [19555, "Loading didn't move the plane, so it's still at San Francisco and can fly."], [26632, "Now P1 is at JFK."]]}, {"click": 3, "sents": [[28958, "Step three: unload C1 at JFK."], [32441, "C1 is in P1, and P1 is at JFK."], [36045, "Now C1 is at JFK."], [38087, "That's half the goal."]]}, {"click": 4, "sents": [[41308, "Steps four to six do the same for the second piece: load C2 into P2 at JFK,"]]}, {"click": 5, "sents": [[49322, "fly P2 to San Francisco,"]]}, {"click": 6, "sents": [[52373, "and unload C2 there."], [53964, "Now both goal facts are true."], [56272, "Six actions, each checked and applied with the RESULT rule."]]}]}, {"n": 15, "title": "Spare Tire: Not Every Action Helps", "sec": "11.1 Defining Classical Planning", "dur": 55433, "clicks": [5177, 12800, 19926, 32747, 44366], "segs": [{"click": 0, "sents": [[500, "The spare tire problem shows that not every action helps."]]}, {"click": 1, "sents": [[5327, "We start with the flat tire on the axle and the spare in the trunk."], [10012, "The goal: the spare on the axle."]]}, {"click": 2, "sents": [[12950, "Here's the Remove schema: if an object is at a location, it's taken off and put on the ground."]]}, {"click": 3, "sents": [[20076, "One schema, but it matches the starting state in two different ways: remove the flat from the axle, and remove the spare from the trunk."], [29337, "That's why the solution uses Remove twice."]]}, {"click": 4, "sents": [[32897, "Now the trap."], [33876, "The car is parked in a bad neighborhood."], [36888, "Leave it overnight, and both tires simply vanish."], [40578, "A planner must avoid actions like this one."]]}, {"click": 5, "sents": [[44516, "The solution: remove the flat, remove the spare, put the spare on the axle."], [50490, "Three steps, and leave-overnight is never used."]]}]}, {"n": 16, "title": "Blocks World: Undo Before You Build", "sec": "11.1 Defining Classical Planning", "dur": 48438, "clicks": [11316, 17815, 23270, 31780], "segs": [{"click": 0, "sents": [[500, "The blocks world is the most famous planning domain of all."], [4858, "It teaches a surprising lesson: sometimes you have to undo before you can build."]]}, {"click": 1, "sents": [[11466, "At the start, block C sits on A, and blocks A and B are on the table."]]}, {"click": 2, "sents": [[17965, "The goal is a tower: A on B, and B on C."]]}, {"click": 3, "sents": [[23420, "To move a block onto another block, we use Move."], [27060, "Both blocks must be clear, with nothing on top of them."]]}, {"click": 4, "sents": [[31930, "But moving a block onto the table needs its own action, MoveToTable."], [37033, "Why?"], [37333, "The table always has room, so we never want a fact like the table is clear to be switched off."], [44387, "A separate action avoids that problem."]]}]}, {"n": 17, "title": "Blocks World: The Solution", "sec": "11.1 Defining Classical Planning", "dur": 46766, "clicks": [3741, 14550, 20814, 28985], "segs": [{"click": 0, "sents": [[500, "Here's the solution, in three moves."]]}, {"click": 1, "sents": [[3891, "First, move C off A and onto the table."], [7149, "This doesn't achieve any goal fact directly, but it clears A, so A can move later."]]}, {"click": 2, "sents": [[14700, "Second, move B onto C."], [16848, "Both are clear, so this is allowed."]]}, {"click": 3, "sents": [[20964, "Third, move A onto B."], [23454, "Now A is on B, and B is on C."], [26893, "Goal reached."]]}, {"click": 4, "sents": [[29135, "Here's the lesson."], [30455, "If the planner had greedily tried to put A on B first, it would find C still sitting on A."], [37057, "Pursuing one goal at a time, without noticing how goals interact, is exactly the trap that early planners fell into."]]}]}, {"n": 18, "title": "Northgate: The Same Structure", "sec": "11.1 Defining Classical Planning", "dur": 38825, "clicks": [6039, 12852, 20788, 26399], "segs": [{"click": 0, "sents": [[500, "Now let's check in with Northgate."], [2732, "Can the same language describe a hospital?"]]}, {"click": 1, "sents": [[6189, "Here's the starting state."], [8201, "Maria, Dr. Okafor, and Nurse Priya are all in pre-op."]]}, {"click": 2, "sents": [[13002, "Operating room 3 is not occupied."], [15716, "And we record who is a patient, a surgeon, and a nurse."]]}, {"click": 3, "sents": [[20938, "The goal: Maria is in recovery, and her surgery is complete."]]}, {"click": 4, "sents": [[26549, "Put this next to Air Cargo."], [28570, "Same structure: objects, a starting state, and a goal."], [32611, "Only the names changed."], [34332, "That's what domain-independent really means."]]}]}, {"n": 19, "title": "Northgate: Four Actions", "sec": "11.1 Defining Classical Planning", "dur": 56531, "clicks": [8756, 18860, 30088, 39460, 46430], "segs": [{"click": 0, "sents": [[500, "Northgate needs four actions."], [2929, "Each changes only a few facts, just like Load, Fly, and Unload."]]}, {"click": 1, "sents": [[8906, "Prep: if the patient and a nurse are in pre-op, the patient becomes prepped."], [14534, "It plays the role of Load: getting the cargo ready."]]}, {"click": 2, "sents": [[19010, "Transfer to OR: if the patient is prepped and the room is free, she moves into the room, and it becomes occupied."], [27329, "That's the big move, like Fly."]]}, {"click": 3, "sents": [[30238, "Here's that action grounded for Maria and OR-3."], [34717, "Every p became Maria, every o-r became OR-3."]]}, {"click": 4, "sents": [[39610, "Transfer to recovery is like Unload: the patient arrives in recovery and the room is freed."]]}, {"click": 5, "sents": [[46580, "And Operate has no Air Cargo match at all."], [49804, "A new domain can add new kinds of actions, not just rename the old ones."]]}]}, {"n": 20, "title": "Northgate: Maria’s Plan", "sec": "11.1 Defining Classical Planning", "dur": 60867, "clicks": [4603, 13740, 23844, 41550, 52124], "segs": [{"click": 0, "sents": [[500, "Now let's plan Maria's journey, step by step."]]}, {"click": 1, "sents": [[4753, "Step one: Nurse Priya preps Maria."], [7485, "They're both in pre-op, so the preconditions hold."], [11503, "Maria is now prepped."]]}, {"click": 2, "sents": [[13890, "Step two: transfer Maria to OR-3."], [16818, "She's prepped, and the room is free."], [20011, "Now she's in OR-3, and it's occupied."]]}, {"click": 3, "sents": [[23994, "Step three: Dr. Okafor operates."], [26468, "Notice that this precondition needs Dr. Okafor in OR-3 too."], [31028, "A complete model would also move him there."], [34352, "The planner checks every precondition, which is exactly how it catches gaps like this."]]}, {"click": 4, "sents": [[41700, "Step four: transfer Maria to recovery."], [45174, "Her surgery is complete, so she moves, and OR-3 is freed."], [50385, "Goal reached."]]}, {"click": 5, "sents": [[52274, "Same rhythm as Air Cargo: check the preconditions, apply the action, update the state, repeat."]]}]}, {"n": 21, "title": "Check Yourself: Defining Planning", "sec": "11.1 Defining Classical Planning", "dur": 50899, "clicks": [12361, 23249, 32073], "segs": [{"click": 0, "sents": [[500, "Let's check yourself on section 11.1."], [3959, "Three questions are on the screen."], [7137, "Pause the video and answer them in your own words."]]}, {"click": 1, "sents": [[12511, "Number one: the RESULT rule starts from the current state, removes everything the action deletes, and adds everything it adds."], [21244, "Nothing else changes."]]}, {"click": 2, "sents": [[23399, "Number two: under the closed-world assumption, any fact that isn't listed in the state is assumed to be false."]]}, {"click": 3, "sents": [[32223, "Number three: the table always has room."], [35262, "A normal Move action would switch a fact like the table is clear on and off, which makes no sense, so moving to the table gets its own action."], [46052, "If you got these, you're ready for section 11.2."]]}]}, {"n": 22, "title": "11.2 Algorithms for Classical Planning", "sec": "11.2 Algorithms for Classical Planning", "dur": 25184, "clicks": [], "segs": [{"click": 0, "sents": [[500, "Section 11.2: Algorithms for Classical Planning."], [4220, "Once a problem is written in PDDL, how do we actually find a plan?"], [9336, "Because PDDL is a description, not a program, we're free to search in different directions."], [16389, "This section covers forward search, backward search, planning as satisfiability, and a few others."]]}]}, {"n": 23, "title": "Three Ways to Search", "sec": "11.2 Algorithms for Classical Planning", "dur": 43919, "clicks": [3897, 15830, 24576, 35725], "segs": [{"click": 0, "sents": [[500, "There are three main ways to search for a plan."]]}, {"click": 1, "sents": [[4047, "Forward search, also called progression, starts at the initial state and applies actions until it reaches the goal."], [12021, "It mirrors how people naturally describe plans."]]}, {"click": 2, "sents": [[15980, "Backward search, also called regression, starts from the goal and asks: what must have been true one step earlier?"]]}, {"click": 3, "sents": [[24726, "SAT planning turns the question into logic."], [28470, "Is there a plan of exactly k steps?"], [31518, "A satisfiability solver answers yes or no."]]}, {"click": 4, "sents": [[35875, "All three are possible because PDDL describes the problem without saying how to solve it."]]}]}, {"n": 24, "title": "Forward Search (Progression)", "sec": "11.2 Algorithms for Classical Planning", "dur": 58072, "clicks": [3819, 10475, 23688, 34419, 46769], "segs": [{"click": 0, "sents": [[500, "Let's look at forward search in more detail."]]}, {"click": 1, "sents": [[3969, "We begin at the initial state: both cargo and both planes at their starting airports."]]}, {"click": 2, "sents": [[10625, "Next, we find every applicable action, meaning every action whose preconditions are true right now."], [18225, "Take Load: it needs the cargo and the plane at the same airport."]]}, {"click": 3, "sents": [[23838, "Try C1, P1, and San Francisco."], [27420, "Is C1 at San Francisco?"], [30167, "Yes."], [30645, "Is P1 at San Francisco?"], [33391, "Yes."]]}, {"click": 4, "sents": [[34569, "So loading C1 into P1 at San Francisco is applicable."], [38502, "The planner applies RESULT to get the next state, and repeats, using any search strategy from Chapter 3."]]}, {"click": 5, "sents": [[46919, "So forward search is ordinary search, with states made of facts."], [51782, "The one thing missing is a good heuristic, and that's section 11.3."]]}]}, {"n": 25, "title": "The Branching Problem", "sec": "11.2 Algorithms for Classical Planning", "dur": 54101, "clicks": [4916, 12930, 18777, 33583, 43843], "segs": [{"click": 0, "sents": [[500, "Forward search is intuitive, but there's a catch."]]}, {"click": 1, "sents": [[5066, "Consider a bigger Air Cargo problem: ten airports, fifty planes, and two hundred pieces of cargo."]]}, {"click": 2, "sents": [[13080, "The actual solution is only forty-one steps long."], [16582, "That sounds manageable."]]}, {"click": 3, "sents": [[18927, "But in every state, there are hundreds or even thousands of applicable actions."], [24555, "Every plane can fly to nine other airports, and every package can be loaded or unloaded."], [30824, "Around two thousand on average."]]}, {"click": 4, "sents": [[33733, "So a blind search tree to depth forty-one has roughly two thousand to the power forty-one nodes."], [40289, "That's far more than could ever be explored."]]}, {"click": 5, "sents": [[43993, "The moral: for forward search, a good heuristic isn't optional."], [48343, "It's the difference between solving instantly and never finishing."]]}]}, {"n": 26, "title": "Backward Search (Regression)", "sec": "11.2 Algorithms for Classical Planning", "dur": 49216, "clicks": [4132, 9273, 17941, 25406, 30704], "segs": [{"click": 0, "sents": [[500, "Backward search works in the opposite direction."]]}, {"click": 1, "sents": [[4282, "We start from the goal, the facts that must be true at the end."]]}, {"click": 2, "sents": [[9423, "We pick a relevant action: one whose effect achieves one of the goal facts, without undoing any other goal fact."]]}, {"click": 3, "sents": [[18091, "Then we regress: we replace the goal with what must have been true just before that action ran."]]}, {"click": 4, "sents": [[25556, "And we keep going until the starting state satisfies the regressed goal."]]}, {"click": 5, "sents": [[30854, "Why bother?"], [31675, "Backward search only considers relevant actions, so it often has far fewer choices."], [37868, "The downside: its states contain variables, which makes good heuristics harder to design."], [44509, "That's why most modern planners search forward."]]}]}, {"n": 27, "title": "Regression: A Worked Example", "sec": "11.2 Algorithms for Classical Planning", "dur": 47910, "clicks": [3401, 7575, 18724, 27705, 34518], "segs": [{"click": 0, "sents": [[500, "Let's regress one goal by hand."]]}, {"click": 1, "sents": [[3551, "Our goal: C2 is at San Francisco."]]}, {"click": 2, "sents": [[7725, "A relevant action is unload C2 from some plane at San Francisco."], [12606, "Its effect adds exactly the fact we want, and doesn't undo anything else."]]}, {"click": 3, "sents": [[18874, "For that unload to work, its preconditions must have held: C2 was in the plane, and the plane was at San Francisco."]]}, {"click": 4, "sents": [[27855, "So the new goal is: take out what the action adds, and put in what it needs."]]}, {"click": 5, "sents": [[34668, "C2 in some plane, and that plane at San Francisco."], [38273, "That's one step closer to the start."], [40869, "Notice the plane is still a variable; the planner hasn't decided which plane yet."]]}]}, {"n": 28, "title": "Planning as Satisfiability (SAT)", "sec": "11.2 Algorithms for Classical Planning", "dur": 58563, "clicks": [6771, 14393, 27684, 40505, 44679, 50290], "segs": [{"click": 0, "sents": [[500, "The third approach doesn't search through states at all."], [4269, "It turns planning into logic."]]}, {"click": 1, "sents": [[6921, "First, fix a plan length, k."], [9576, "We ask: is there a plan with exactly k steps?"]]}, {"click": 2, "sents": [[14543, "Then write every possible action, at every time step, as a true-or-false variable."], [21380, "Load C1 into P1 at San Francisco at time one, at time two, and so on."]]}, {"click": 3, "sents": [[27834, "Add axioms: an action's preconditions must hold when it fires; only one action happens per step; and rules for what changes and what stays the same."]]}, {"click": 4, "sents": [[40655, "Hand the whole formula to a SAT solver."]]}, {"click": 5, "sents": [[44829, "If the answer is satisfiable, the solver's true variables are the plan."]]}, {"click": 6, "sents": [[50440, "If it's unsatisfiable, there's no plan of that length, so we increase k by one and try again."]]}]}, {"n": 29, "title": "What the SAT Clauses Say", "sec": "11.2 Algorithms for Classical Planning", "dur": 51750, "clicks": [5177, 19827, 29356, 33139, 40839], "segs": [{"click": 0, "sents": [[500, "Let's read a few SAT clauses in plain English."]]}, {"click": 1, "sents": [[5327, "The superscript is the time step."], [8117, "This precondition clause says: if we load C1 into P1 at San Francisco at time t, then C1 must already be at San Francisco at time t."]]}, {"click": 2, "sents": [[19977, "These effect clauses say: if the load happens at time t, then at time t plus one, C1 is in the plane,"]]}, {"click": 3, "sents": [[29506, "and C1 is no longer at the airport."]]}, {"click": 4, "sents": [[33289, "Grounded at time one, the precondition clause becomes one specific line of logic, ready for the solver."]]}, {"click": 5, "sents": [[40989, "Each clause on its own looks trivial."], [43516, "The power comes from thousands of them locking together, so that any satisfying answer is a valid plan."]]}]}, {"n": 30, "title": "Other Approaches", "sec": "11.2 Algorithms for Classical Planning", "dur": 54681, "clicks": [7398, 19487, 29983, 42334], "segs": [{"click": 0, "sents": [[500, "Forward, backward, and SAT aren't the only options."], [4547, "Here are three more, briefly."]]}, {"click": 1, "sents": [[7548, "Graphplan builds a special data structure, a planning graph, that records which facts and actions can and can't happen together."], [16073, "That makes it very fast to pull out a plan."]]}, {"click": 2, "sents": [[19637, "Situation calculus describes planning directly in first-order logic."], [24395, "It's very expressive and important in theory, but less used in practice."]]}, {"click": 3, "sents": [[30133, "And a CSP encoding treats a k-step plan as constraint satisfaction, from Chapter 5."], [36623, "Each time step is a variable, and its possible values are actions."]]}, {"click": 4, "sents": [[42484, "All of these make the same point: because PDDL describes the problem rather than prescribing a method, we're free to use whichever approach suits the problem."]]}]}, {"n": 31, "title": "Partial-Order Planning", "sec": "11.2 Algorithms for Classical Planning", "dur": 51123, "clicks": [5177, 14001, 16817, 21305, 32376], "segs": [{"click": 0, "sents": [[500, "One last idea in this section: partial-order planning."]]}, {"click": 1, "sents": [[5327, "So far, every plan has been a strict sequence."], [8605, "But look at the spare tire."], [10529, "We need to remove the flat from the axle,"]]}, {"click": 2, "sents": [[14151, "and remove the spare from the trunk,"]]}, {"click": 3, "sents": [[16967, "and both must happen before we put the spare on the axle."]]}, {"click": 4, "sents": [[21455, "But the two removes don't affect each other."], [24343, "Either can go first."], [25656, "A partial-order plan leaves that choice open, instead of forcing an order that doesn't matter."]]}, {"click": 5, "sents": [[32526, "Partial-order planning dominated in the 1980s and 90s."], [36408, "Today, forward search with strong heuristics usually wins."], [40578, "But when people have to read and check a plan, such as spacecraft and Mars rover operators, partial-order plans are still popular."]]}]}, {"n": 32, "title": "Check Yourself: Planning Algorithms", "sec": "11.2 Algorithms for Classical Planning", "dur": 48678, "clicks": [10532, 24712, 37141], "segs": [{"click": 0, "sents": [[500, "Let's check yourself on section 11.2."], [4080, "Pause the video and answer the three questions on the screen."]]}, {"click": 1, "sents": [[10682, "Number one: backward search considers far fewer actions, because it only looks at relevant ones."], [17318, "But its states contain variables, which makes good heuristics harder."], [22087, "Forward search is the reverse."]]}, {"click": 2, "sents": [[24862, "Number two: SAT planning asks whether there's a plan of exactly k steps."], [31071, "If the answer is unsatisfiable, increase k by one and ask again."]]}, {"click": 3, "sents": [[37291, "Number three: a partial-order plan leaves actions unordered when their order doesn't matter, so the plan is a graph rather than a single sequence."]]}]}, {"n": 33, "title": "11.3 Heuristics for Planning", "sec": "11.3 Heuristics for Planning", "dur": 25654, "clicks": [], "segs": [{"click": 0, "sents": [[500, "Section 11.3: Heuristics for Planning."], [3318, "We saw that forward search is hopeless without a good heuristic."], [8064, "The good news: because planning problems are written as facts and actions, the computer can work out good heuristics on its own."], [17557, "The trick, over and over, is to relax the problem and measure how hard the easier version is."]]}]}, {"n": 34, "title": "Heuristics and Admissibility", "sec": "11.3 Heuristics for Planning", "dur": 54728, "clicks": [5177, 14001, 25386, 33086, 43347], "segs": [{"click": 0, "sents": [[500, "Let's start with what a heuristic is, and what makes a good one."]]}, {"click": 1, "sents": [[5327, "A heuristic, h of s, is an informed guess: roughly how many actions remain from state s to the goal?"]]}, {"click": 2, "sents": [[14151, "A heuristic is admissible if it never overestimates. h of s must be less than or equal to h-star of s, the true remaining cost."]]}, {"click": 3, "sents": [[25536, "Suppose the truth is three actions."], [28385, "A guess of two is admissible: two is at most three."]]}, {"click": 4, "sents": [[33236, "A guess of four is not: it overestimates."], [36423, "With an admissible heuristic, A-star search is guaranteed to find an optimal plan."]]}, {"click": 5, "sents": [[43497, "Here's the recipe we'll use all section: relax the problem by removing some restriction, solve the easier version, and use its cost as the heuristic."]]}]}, {"n": 35, "title": "Ignore Preconditions", "sec": "11.3 Heuristics for Planning", "dur": 50052, "clicks": [4916, 12695, 17261, 27522, 41153], "segs": [{"click": 0, "sents": [[500, "Our first relaxation: ignore preconditions."]]}, {"click": 1, "sents": [[5066, "We delete every precondition from every action."], [8980, "Now any action can happen at any time."]]}, {"click": 2, "sents": [[12845, "At the start of Air Cargo, two goal facts are missing."]]}, {"click": 3, "sents": [[17411, "With no preconditions, the relaxed planner can just unload C1 at JFK, without ever loading it or flying the plane."], [26061, "Same for C2."]]}, {"click": 4, "sents": [[27672, "So the heuristic says two."], [29627, "The real plan takes six."], [31431, "Two is at most six, so it's admissible, but it's a loose estimate, because it skips the hard part of making actions legal."]]}, {"click": 5, "sents": [[41303, "It's the same idea as the misplaced-tiles heuristic for the eight-puzzle: let every tile jump straight to its goal square."]]}]}, {"n": 36, "title": "The Set-Cover Heuristic", "sec": "11.3 Heuristics for Planning", "dur": 60632, "clicks": [5177, 17267, 28076, 40583, 48754], "segs": [{"click": 0, "sents": [[500, "A closely related idea treats the goal like a shopping list."]]}, {"click": 1, "sents": [[5327, "Take each action, remove its preconditions, and keep only the effects that are goal facts."], [11940, "Then find the fewest actions that together cover every goal fact."]]}, {"click": 2, "sents": [[17417, "Example A: we want A on B, and B on C."], [21183, "No single action does both, so we need two."], [25445, "The heuristic is two."]]}, {"click": 3, "sents": [[28226, "Example B: we want C on the table, and A clear."], [32462, "One action, moving C to the table, produces both facts at once."], [38140, "The heuristic is one."]]}, {"click": 4, "sents": [[40733, "Both goals have two facts, but the heuristics differ, because set-cover counts actions, not facts."]]}, {"click": 5, "sents": [[48904, "Finding the true minimum is the classic set-cover problem, which is NP-hard."], [54578, "A greedy choice is fast and close, but it can lose admissibility."]]}]}, {"n": 37, "title": "Ignore Delete Lists", "sec": "11.3 Heuristics for Planning", "dur": 53657, "clicks": [7398, 15647, 20213, 26321, 37391], "segs": [{"click": 0, "sents": [[500, "Now one of the most important ideas in the whole chapter: ignore delete lists."]]}, {"click": 1, "sents": [[7548, "Here, we pretend actions only ever add facts."], [10814, "The minus delete part of the RESULT rule is simply dropped."]]}, {"click": 2, "sents": [[15797, "Take loading C1 into P1 at San Francisco."]]}, {"click": 3, "sents": [[20363, "Really, C1 stops being at San Francisco."], [23909, "That fact is deleted."]]}, {"click": 4, "sents": [[26471, "In the relaxed version, nothing is deleted."], [29774, "C1 is at San Francisco and in the plane at the same time."], [34153, "Facts pile up instead of competing."]]}, {"click": 5, "sents": [[37541, "Because nothing can ever get worse, simple hill-climbing finds good relaxed plans fast, with no dead ends."], [45446, "This is the heuristic behind FF, Fast Forward, one of the most successful planners ever built."]]}]}, {"n": 38, "title": "The Same Heuristics at Northgate", "sec": "11.3 Heuristics for Planning", "dur": 47236, "clicks": [4759, 12225, 24158, 38180], "segs": [{"click": 0, "sents": [[500, "Do these relaxations work for a hospital?"], [3369, "Let's check."]]}, {"click": 1, "sents": [[4909, "Ignore delete lists: start with Maria in pre-op and prepped, and transfer her to OR-3."]]}, {"click": 2, "sents": [[12375, "In the relaxed result, nothing is removed."], [15651, "Maria is in pre-op and in OR-3 at the same time."], [19396, "Physically absurd, but perfectly fine for a heuristic."]]}, {"click": 3, "sents": [[24308, "Ignore preconditions: Operate needs nothing, so surgery complete can happen in one imaginary step, without prepping Maria or bringing in Dr. Okafor."], [35447, "Fast, but far too optimistic."]]}, {"click": 4, "sents": [[38330, "Nobody had to invent a hospital heuristic."], [41327, "The same relaxation code reads whatever action schemas it's given."]]}]}, {"n": 39, "title": "Symmetry Reduction", "sec": "11.3 Heuristics for Planning", "dur": 42796, "clicks": [6536, 13923, 25307, 33321], "segs": [{"click": 0, "sents": [[500, "Another way to speed up planning is to avoid exploring states that are really the same."]]}, {"click": 1, "sents": [[6686, "Suppose twelve blocks sit on a table, and the goal is block A on top of a three-block tower."]]}, {"click": 2, "sents": [[14073, "The first move must put some block x on some block y, both different from A."], [19873, "That's eleven times ten, a hundred and ten possible first moves."]]}, {"click": 3, "sents": [[25457, "But they're all the same."], [26920, "Whether block four or block seven goes on the bottom makes no difference to the rest of the problem."]]}, {"click": 4, "sents": [[33471, "Symmetry reduction keeps one representative and prunes the rest."], [38113, "That turns an expensive search into a cheap one."]]}]}, {"n": 40, "title": "Serializable Subgoals", "sec": "11.3 Heuristics for Planning", "dur": 46160, "clicks": [5883, 14785, 21206, 23552, 28771], "segs": [{"click": 0, "sents": [[500, "Sometimes a problem's structure lets us avoid backtracking entirely."]]}, {"click": 1, "sents": [[6033, "Subgoals are serializable if there's some order in which to achieve them, so that you never have to undo one you already finished."]]}, {"click": 2, "sents": [[14935, "Building a tower from the bottom up is the classic example."], [19051, "Place the bottom block,"]]}, {"click": 3, "sents": [[21356, "then the next,"]]}, {"click": 4, "sents": [[23702, "then the top."], [24715, "You never disturb a block you already placed."]]}, {"click": 5, "sents": [[28921, "NASA's Remote Agent discovered that spacecraft commands are serializable, which isn't surprising, since engineers design spacecraft to be controllable."], [38888, "That removed almost all backtracking, and made it fast enough to fly Deep Space One in 1999."]]}]}, {"n": 41, "title": "Preferred Actions", "sec": "11.3 Heuristics for Planning", "dur": 43057, "clicks": [6039, 15726, 23975, 29351], "segs": [{"click": 0, "sents": [[500, "Here's a technique that accepts a little risk in exchange for a lot of speed."]]}, {"click": 1, "sents": [[6189, "First, quickly solve a relaxed version of the problem, for example by ignoring delete lists."], [12856, "That gives a rough relaxed plan."]]}, {"click": 2, "sents": [[15876, "Call an action preferred if it's a step in that relaxed plan, or if it achieves one of that step's preconditions."]]}, {"click": 3, "sents": [[24125, "Then search the preferred actions first, and set the others aside."]]}, {"click": 4, "sents": [[29501, "This is called forward pruning."], [31795, "Unlike an admissible heuristic, it can occasionally miss the truly best plan."], [37492, "In exchange, it often finds a good plan almost immediately."]]}]}, {"n": 42, "title": "State Abstraction", "sec": "11.3 Heuristics for Planning", "dur": 47001, "clicks": [5491, 13819, 21598, 29847], "segs": [{"click": 0, "sents": [[500, "Instead of relaxing actions, we can shrink the number of states."]]}, {"click": 1, "sents": [[5641, "An abstraction maps many detailed states onto one simpler state."], [10890, "Here, a plane with full fuel."]]}, {"click": 2, "sents": [[13969, "If we ignore all fuel facts, that state becomes just: P1 and C1 at San Francisco."]]}, {"click": 3, "sents": [[21748, "Full fuel, half fuel, low fuel: three different real states all map to the same abstract one."]]}, {"click": 4, "sents": [[29997, "The abstract problem is easier, so its solution cost never exceeds the real cost."], [35539, "That makes it admissible."], [37249, "The full Air Cargo problem has around ten to the four hundred and fifth states, and abstraction can cut that down enormously."]]}]}, {"n": 43, "title": "Decomposition: Max or Sum?", "sec": "11.3 Heuristics for Planning", "dur": 54859, "clicks": [11159, 16927, 28076, 34732, 43948], "segs": [{"click": 0, "sents": [[500, "Decomposition splits a big goal into smaller subgoals, solves each one, then combines the costs."], [8082, "But how we combine them matters."]]}, {"click": 1, "sents": [[11309, "Suppose three subgoals cost three, five, and four on their own."]]}, {"click": 2, "sents": [[17077, "Taking the maximum gives five."], [19269, "That's always admissible, because the whole problem is at least as hard as its hardest piece."], [26065, "But it can be loose."]]}, {"click": 3, "sents": [[28226, "Taking the sum gives twelve."], [30311, "That's often more accurate, but it isn't admissible."]]}, {"click": 4, "sents": [[34882, "Here's why."], [35800, "Three pieces of cargo all need to reach JFK."], [39474, "One flight of P1 can deliver all three at once."]]}, {"click": 5, "sents": [[44098, "Summing three separate costs counts that flight three times, and overestimates."], [49652, "Shared work breaks the independence that the sum assumes."]]}]}, {"n": 44, "title": "Heuristics: Which One, When?", "sec": "11.3 Heuristics for Planning", "dur": 53918, "clicks": [6379, 15595, 20814, 28123, 37574], "segs": [{"click": 0, "sents": [[500, "Let's pull this section together."], [3086, "Six ideas, one underlying strategy."]]}, {"click": 1, "sents": [[6529, "Ignoring preconditions is very fast but loose."], [10190, "Set cover counts actions, and is solved greedily in practice."]]}, {"click": 2, "sents": [[15745, "Ignoring delete lists is strong, and it powers the FF planner."]]}, {"click": 3, "sents": [[20964, "Symmetry reduction and serializable subgoals prune the search, rather than estimating a number."]]}, {"click": 4, "sents": [[28273, "Abstraction is admissible if done carefully, and for decomposition, max is safe while sum is strong but risky."]]}, {"click": 5, "sents": [[37724, "Behind all of them is one strategy: relax the problem, measure the easier version, and use that to guide search."], [46704, "Modern planners like FF and Fast Downward combine several of these at once."]]}]}, {"n": 45, "title": "Check Yourself: Planning Heuristics", "sec": "11.3 Heuristics for Planning", "dur": 49880, "clicks": [11316, 24059, 35364], "segs": [{"click": 0, "sents": [[500, "Let's check yourself on section 11.3."], [4376, "Pause the video and answer the three questions on the screen."]]}, {"click": 1, "sents": [[11466, "Number one: ignoring delete lists keeps all the preconditions, so the relaxed plan still has to do the real work of making actions legal."], [21114, "That gives a much closer estimate."]]}, {"click": 2, "sents": [[24209, "Number two: set cover counts actions, not facts."], [28416, "Sometimes one action produces two goal facts at once, so the count drops."]]}, {"click": 3, "sents": [[35514, "Number three: max is always admissible, because the whole problem is at least as hard as its hardest piece."], [43473, "Sum can double-count work that subgoals share, so it can overestimate."]]}]}, {"n": 46, "title": "11.4 Hierarchical Planning", "sec": "11.4 Hierarchical Planning", "dur": 26464, "clicks": [], "segs": [{"click": 0, "sents": [[500, "Section 11.4: Hierarchical Planning."], [3161, "Flat planning strings together primitive actions one at a time."], [7818, "That's fine for short tasks, but hopeless for long ones."], [11958, "People plan in layers: first the big steps, then the details."], [16467, "This section shows how a planner can do the same, and even prove a high-level plan works before filling in the details."]]}]}, {"n": 47, "title": "Why Hierarchy?", "sec": "11.4 Hierarchical Planning", "dur": 48955, "clicks": [4524, 10292, 18959, 26190, 37339], "segs": [{"click": 0, "sents": [[500, "Why do we need hierarchy?"], [2237, "Because of the scale gap."]]}, {"click": 1, "sents": [[4674, "Think about a two-week vacation in Hawaii."], [7804, "At the top, it's one task."]]}, {"click": 2, "sents": [[10442, "Break it into a few high-level steps: go to the San Francisco airport, fly to Honolulu, enjoy the trip."]]}, {"click": 3, "sents": [[19109, "Each of those breaks down further."], [21497, "Going to the airport means ordering a car and riding there."]]}, {"click": 4, "sents": [[26340, "Keep going down, and you reach millions of tiny primitive actions, like bending a knee by five degrees."], [33329, "No flat planner could string all of those together."]]}, {"click": 5, "sents": [[37489, "People solve this with layers, just as software uses subroutines and organizations use management levels."], [44723, "Hierarchical planning borrows the same idea."]]}]}, {"n": 48, "title": "High-Level Actions and Refinements", "sec": "11.4 Hierarchical Planning", "dur": 47753, "clicks": [7006, 16222, 22878, 26974, 35563], "segs": [{"click": 0, "sents": [[500, "The building block of hierarchical planning is the high-level action, or HLA."]]}, {"click": 1, "sents": [[7156, "Go from home to the San Francisco airport is a high-level action."], [11481, "It isn't primitive; it can be carried out in more than one way."]]}, {"click": 2, "sents": [[16372, "Refinement one: drive to the long-term parking lot, then take the shuttle to the airport."]]}, {"click": 3, "sents": [[23028, "Refinement two: take a taxi straight there."]]}, {"click": 4, "sents": [[27124, "A refinement made only of primitive actions, ones the agent can execute directly, is called an implementation."]]}, {"click": 5, "sents": [[35713, "Refinements encode real know-how."], [38006, "The library never suggests buying milk on the way to the airport."], [42523, "A good library is expert knowledge built into the planner."]]}]}, {"n": 49, "title": "“At Least One” Implementation Is Enough", "sec": "11.4 Hierarchical Planning", "dur": 56687, "clicks": [4759, 14132, 24001, 34967, 43791], "segs": [{"click": 0, "sents": [[500, "Here's a subtle definition that sets up the rest of this section."]]}, {"click": 1, "sents": [[4909, "A high-level plan achieves the goal if at least one of its implementations achieves it."], [11145, "Not every implementation."], [12937, "Just one."]]}, {"click": 2, "sents": [[14282, "That's because the agent itself chooses which implementation to run."], [18673, "This isn't like nondeterminism, where nature makes the choice against you."]]}, {"click": 3, "sents": [[24151, "The simplest hierarchical algorithm starts with one top-level action, Act, and repeatedly replaces a high-level action with one of its refinements."]]}, {"click": 4, "sents": [[35117, "When the plan is fully primitive, it simulates it to see if it reaches the goal."], [40768, "If not, it tries other refinements."]]}, {"click": 5, "sents": [[43941, "This works, but it still ends up trying every combination down to the primitive level."], [49782, "The real payoff comes when we can trust a high-level plan without refining it fully."]]}]}, {"n": 50, "title": "The Payoff: Exponential Savings", "sec": "11.4 Hierarchical Planning", "dur": 60480, "clicks": [5256, 16718, 32021, 40531], "segs": [{"click": 0, "sents": [[500, "When hierarchy works well, the savings are dramatic."]]}, {"click": 1, "sents": [[5406, "Flat search costs about b to the d: b choices at each step, for d steps."], [11321, "With ten choices and seven steps, that's ten million nodes."]]}, {"click": 2, "sents": [[16868, "With a regular hierarchy, where each high-level action has r refinements of k steps each, the cost is about r to the power d minus one over k minus one."], [28078, "That's roughly the k-th root of the flat cost."]]}, {"click": 3, "sents": [[32171, "With two refinements of three steps each, and the same depth of seven, that's two cubed: just eight possibilities."]]}, {"click": 4, "sents": [[40681, "This is real."], [41590, "Hitachi used a hierarchical planner, O-PLAN, to schedule a factory with three hundred and fifty products, thirty-five machines, and over two thousand operations: a thirty-day, three-shift schedule."], [55364, "Only possible with a good library of high-level actions."]]}]}, {"n": 51, "title": "Do We Have to Refine Everything?", "sec": "11.4 Hierarchical Planning", "dur": 45120, "clicks": [7581, 14158, 21624, 32773], "segs": [{"click": 0, "sents": [[500, "Here's the key question."], [2150, "Do we really have to plan every detail before we know a plan will work?"]]}, {"click": 1, "sents": [[7731, "Take the plan: drive to the long-term parking lot, then take the shuttle to the airport."]]}, {"click": 2, "sents": [[14308, "Obviously, that gets you to the airport."], [16682, "You don't need to work out the exact route or the parking spot to know it."]]}, {"click": 3, "sents": [[21774, "So the goal is to describe what high-level actions achieve directly, the way we describe primitive actions, and check a high-level plan without refining it."]]}, {"click": 4, "sents": [[32923, "For that to be safe, we need the downward refinement property: if a high-level plan claims to reach the goal, at least one real implementation must actually reach it."]]}]}, {"n": 52, "title": "Angelic Semantics: The Reachable Set", "sec": "11.4 Hierarchical Planning", "dur": 56400, "clicks": [5961, 13897, 23766, 30108, 41649], "segs": [{"click": 0, "sents": [[500, "To check high-level plans directly, we need the idea of a reachable set."]]}, {"click": 1, "sents": [[6111, "REACH of s and h is the set of all states that some implementation of h can reach from s."]]}, {"click": 2, "sents": [[14047, "Take going from San Francisco to New York."], [17311, "It has three implementations: fly direct, fly via Denver, or take the train."]]}, {"click": 3, "sents": [[23916, "All three end in New York, so the reachable set is just: at New York."]]}, {"click": 4, "sents": [[30258, "Now compare two kinds of choice."], [32718, "In Chapter 4, demonic nondeterminism: an adversary picks the outcome, so every possible outcome must succeed."]]}, {"click": 5, "sents": [[41799, "Here, angelic: the agent itself picks, later, when it acts."], [46317, "So one successful implementation is enough."], [49610, "More refinements can only help, because the agent will choose a good one."]]}]}, {"n": 53, "title": "Angelic Semantics: A Worked Example", "sec": "11.4 Hierarchical Planning", "dur": 39504, "clicks": [2774, 10240, 16974, 28593], "segs": [{"click": 0, "sents": [[500, "Let's work through the test."]]}, {"click": 1, "sents": [[2924, "Here are the three implementations of go from San Francisco to New York, with very different travel times."]]}, {"click": 2, "sents": [[10390, "The reachable set is: at New York."], [13867, "The goal is: at New York."]]}, {"click": 3, "sents": [[17124, "The success test asks: do they overlap?"], [20232, "The upside-down U means intersection, and the crossed circle means empty."], [26050, "The overlap is not empty."]]}, {"click": 4, "sents": [[28743, "So the plan is feasible."], [30481, "And we proved that without choosing a flight, a seat, or an airline."], [35407, "That's the exponential saving in action."]]}]}, {"n": 54, "title": "Optimistic and Pessimistic Bounds", "sec": "11.4 Hierarchical Planning", "dur": 66849, "clicks": [12283, 29910, 38316, 46566, 55625], "segs": [{"click": 0, "sents": [[500, "In real problems, an HLA can have so many implementations that its exact reachable set is too complicated to write down."], [9547, "So we use two bounds instead."]]}, {"click": 1, "sents": [[12433, "The pessimistic set, REACH-minus, includes only what certainly happens."], [18129, "It understates."], [19332, "The optimistic set, REACH-plus, includes everything that might happen."], [24948, "It overstates."], [26071, "The true reachable set sits between them."]]}, {"click": 2, "sents": [[30060, "If even the optimistic set misses the goal, the plan definitely fails."], [34964, "We can prune it without looking further."]]}, {"click": 3, "sents": [[38466, "If even the pessimistic set hits the goal, the plan definitely works."], [43380, "We can commit to it and refine later."]]}, {"click": 4, "sents": [[46716, "If the optimistic set hits but the pessimistic set misses, we genuinely don't know yet."], [52932, "That part needs to be refined."]]}, {"click": 5, "sents": [[55775, "It's how people plan a Hawaii trip: two lazy days on each island sounds fine at the high level, but the ferry connections need working out before you can be sure."]]}]}, {"n": 55, "title": "Angelic Search", "sec": "11.4 Hierarchical Planning", "dur": 57340, "clicks": [5726, 16692, 27031, 33766, 45385], "segs": [{"click": 0, "sents": [[500, "Put the bounds to work, and you get an algorithm called angelic search."]]}, {"click": 1, "sents": [[5876, "Angelic search prunes high-level plans that provably fail, commits to plans that provably work, and refines only the parts that are genuinely uncertain."]]}, {"click": 2, "sents": [[16842, "The textbook compares algorithms on a vacuum world."], [20328, "Flat breadth-first search costs about five to the d, and can't even clean two small rooms."]]}, {"click": 3, "sents": [[27181, "Hierarchical search without bounds is still exponential, because it tries every refinement."]]}, {"click": 4, "sents": [[33916, "Angelic search is roughly linear in the number of squares."], [37899, "It commits to a good high-level sequence, clean this room, then go to the next, and ignores the rest."]]}, {"click": 5, "sents": [[45535, "The textbook draws a striking conclusion: people solve complex problems not through raw search power, but through skill at abstracting and decomposing them."]]}]}, {"n": 56, "title": "A Northgate HLA: Admit(Maria)", "sec": "11.4 Hierarchical Planning", "dur": 54859, "clicks": [6196, 18782, 28233, 34967, 42198], "segs": [{"click": 0, "sents": [[500, "Let's apply this at Northgate, with a high-level action: admit Maria."]]}, {"click": 1, "sents": [[6346, "Admit Maria has two refinements."], [8951, "The scheduled intake: register, prep, transfer to the operating room."], [14569, "Calm and orderly, but it assumes a free room."]]}, {"click": 2, "sents": [[18932, "The emergency fast-track: a triage override, then transfer."], [23501, "It skips paperwork and can bump a lower-priority case."]]}, {"click": 3, "sents": [[28383, "Now suppose OR-3 is occupied."], [31034, "Can admit Maria still reach the goal?"]]}, {"click": 4, "sents": [[35117, "The scheduled refinement misses, because it needs a free room."], [39291, "But the fast-track refinement hits."]]}, {"click": 5, "sents": [[42348, "Since at least one implementation succeeds, admit Maria is feasible."], [47442, "And we decided that without choosing which case gets bumped or which nurse assists."]]}]}, {"n": 57, "title": "Check Yourself: Hierarchical Planning", "sec": "11.4 Hierarchical Planning", "dur": 46667, "clicks": [9879, 21655, 34398], "segs": [{"click": 0, "sents": [[500, "Let's check yourself on section 11.4."], [4389, "Pause the video and answer the three questions."]]}, {"click": 1, "sents": [[10029, "Number one: a high-level action can be broken down in different ways."], [14928, "An implementation is a refinement made only of primitive actions the agent can execute."]]}, {"click": 2, "sents": [[21805, "Number two: angelic means the agent picks the outcome, so one success is enough."], [28495, "Demonic means an adversary picks, so every outcome must succeed."]]}, {"click": 3, "sents": [[34548, "Number three: if the optimistic set meets the goal but the pessimistic set doesn't, the plan might work but isn't certain."], [43312, "Refine it further to find out."]]}]}, {"n": 58, "title": "11.5 Nondeterministic Domains", "sec": "11.5 Nondeterministic Domains", "dur": 23826, "clicks": [], "segs": [{"click": 0, "sents": [[500, "Section 11.5: Planning and Acting in Nondeterministic Domains."], [5119, "So far, the agent could see everything, and every action did exactly what it promised."], [11526, "Real worlds aren't like that."], [13686, "This section drops those assumptions, and shows how planning still works when the agent has to sense, adapt, and repair."]]}]}, {"n": 59, "title": "From Classical to Online Planning", "sec": "11.5 Nondeterministic Domains", "dur": 46996, "clicks": [6118, 12852, 20631, 28724, 35772], "segs": [{"click": 0, "sents": [[500, "Here's the journey this section takes, from the fully known world to the real one."]]}, {"click": 1, "sents": [[6268, "Classical planning, which we've done so far: one known state, and one fixed plan."]]}, {"click": 2, "sents": [[13002, "Sensorless planning: the agent isn't sure what state it's in, and it has no sensors to find out."]]}, {"click": 3, "sents": [[20781, "Contingent planning: now the agent has sensors, and the plan itself branches on what it observes."]]}, {"click": 4, "sents": [[28874, "Online planning: act, watch what happens, and repair the plan when something goes wrong."]]}, {"click": 5, "sents": [[35922, "The good news: most of what we've built, states as facts, the RESULT rule, relaxation heuristics, carries over with only small changes."]]}]}, {"n": 60, "title": "The Running Example: Matching Paint", "sec": "11.5 Nondeterministic Domains", "dur": 39974, "clicks": [5412, 12382, 19612, 29063], "segs": [{"click": 0, "sents": [[500, "This section uses one running example: painting furniture."]]}, {"click": 1, "sents": [[5562, "We have a table, a chair, and two cans of paint."], [9420, "Only the table starts in view."]]}, {"click": 2, "sents": [[12532, "The goal: the chair and the table are the same color."], [16557, "Any color, as long as they match."]]}, {"click": 3, "sents": [[19762, "And here's something new: a percept schema."], [23092, "It says: whenever an object is in view, the agent perceives its color."]]}, {"click": 4, "sents": [[29213, "The table is in view from the start, so the agent learns its color immediately."], [34686, "A percept schema is the planner's model of its own sensors."]]}]}, {"n": 61, "title": "Sensorless Planning: Belief States", "sec": "11.5 Nondeterministic Domains", "dur": 43266, "clicks": [5021, 15438, 24889, 31310], "segs": [{"click": 0, "sents": [[500, "Start with the hardest case: no sensors at all."]]}, {"click": 1, "sents": [[5171, "The agent doesn't know which world it's in."], [8266, "So instead of one state, it keeps a belief state: the set of every world that might be real."]]}, {"click": 2, "sents": [[15588, "Can one has paint, but the agent hasn't seen what color."], [19849, "So there are two possible worlds: in one, the paint is red,"]]}, {"click": 3, "sents": [[25039, "in the other, it's blue."], [27000, "One belief state, holding two physical states."]]}, {"click": 4, "sents": [[31460, "And notice what happens to the closed-world assumption from section 11.1."], [36656, "If a fact isn't listed, we can't say it's false anymore."], [40642, "It's simply unknown."]]}]}, {"n": 62, "title": "Updating Beliefs — and the Coercion Trick", "sec": "11.5 Nondeterministic Domains", "dur": 55512, "clicks": [7241, 13975, 25830, 32407, 43478], "segs": [{"click": 0, "sents": [[500, "Can the agent solve the paint problem with no sensors at all?"], [5280, "Surprisingly, yes."]]}, {"click": 1, "sents": [[7391, "We start with two possible worlds: can one is red, or can one is blue."]]}, {"click": 2, "sents": [[14125, "Paint the chair from can one."], [16435, "Now, in world one, the chair is red; in world two, it's blue."], [21295, "The RESULT rule is applied to every world at once."]]}, {"click": 3, "sents": [[25980, "Then paint the table from the same can."], [28996, "In each world, the table now matches."]]}, {"click": 4, "sents": [[32557, "Check the goal in every world: red equals red, blue equals blue."], [37402, "The goal holds either way, even though the agent never learned the color."]]}, {"click": 5, "sents": [[43628, "This trick is called coercion."], [45696, "Instead of finding out the hidden fact, the agent chooses actions that make the goal true whatever that fact turns out to be."]]}]}, {"n": 63, "title": "Conditional Effects", "sec": "11.5 Nondeterministic Domains", "dur": 54707, "clicks": [6457, 20715, 33692, 42517], "segs": [{"click": 0, "sents": [[500, "Belief states have a dark side."], [2929, "Some actions make them grow very fast."]]}, {"click": 1, "sents": [[6607, "In the vacuum world, the Suck action cleans the left square if the robot is on the left, and the right square if it's on the right."], [15487, "Its effect depends on where it is."], [17792, "That's called a conditional effect."]]}, {"click": 2, "sents": [[20865, "If the robot doesn't know where it is, both outcomes must be kept, joined by or: on the left with the left square clean, or on the right with the right square clean."]]}, {"click": 3, "sents": [[33842, "Chain more actions like that, and the number of possibilities can double each time."], [39324, "The belief state can grow exponentially."]]}, {"click": 4, "sents": [[42667, "The practical fix: choose plans that keep the belief state simple."], [48257, "Move right, suck, move left, suck."], [51137, "Every step keeps it compact."]]}]}, {"n": 64, "title": "Contingent Planning", "sec": "11.5 Nondeterministic Domains", "dur": 44906, "clicks": [5256, 18312, 24341, 28201, 32950], "segs": [{"click": 0, "sents": [[500, "Now let's give the agent sensors, and let the plan branch."]]}, {"click": 1, "sents": [[5406, "A contingent plan can include if, then, else."], [8716, "Here, the agent starts by looking at the table and the chair."], [13202, "Looking costs nothing, and it might reveal they already match."]]}, {"click": 2, "sents": [[18462, "If they're the same color, do nothing."], [21728, "NoOp means no operation."]]}, {"click": 3, "sents": [[24491, "Otherwise, open a can and look inside."]]}, {"click": 4, "sents": [[28351, "Suppose the agent sees a red table and a blue chair."]]}, {"click": 5, "sents": [[33100, "Red isn't blue, so the condition is false, and the plan takes the else branch."], [38728, "The decision is made while acting, using what the agent has observed."]]}]}, {"n": 65, "title": "The Full Contingent Paint Plan", "sec": "11.5 Nondeterministic Domains", "dur": 43678, "clicks": [6614, 13192, 17366, 23395, 28457], "segs": [{"click": 0, "sents": [[500, "Here's the complete contingent plan for the paint problem."], [4086, "It has three layers of fallback."]]}, {"click": 1, "sents": [[6764, "Layer one: look at the table and chair."], [9904, "If they already match, do nothing."]]}, {"click": 2, "sents": [[13342, "Otherwise, open both cans and look at the paint."]]}, {"click": 3, "sents": [[17516, "Layer two: if a can matches the table, paint only the chair with it."]]}, {"click": 4, "sents": [[23545, "Or if a can matches the chair, paint only the table."]]}, {"click": 5, "sents": [[28607, "Layer three: if nothing matches, paint both from can one."], [32927, "That's the coercion trick, used as the last resort."], [36793, "Gather cheap information first, and fall back on coercion only if you must."]]}]}, {"n": 66, "title": "Online Planning: Act, Observe, Repair", "sec": "11.5 Nondeterministic Domains", "dur": 38004, "clicks": [4838, 7340, 10391, 13860, 16676, 27825], "segs": [{"click": 0, "sents": [[500, "The most flexible approach of all is online planning."]]}, {"click": 1, "sents": [[4988, "The agent acts,"]]}, {"click": 2, "sents": [[7490, "observes what actually happened,"]]}, {"click": 3, "sents": [[10541, "repairs the plan if something went wrong,"]]}, {"click": 4, "sents": [[14010, "and continues toward the goal."]]}, {"click": 5, "sents": [[16826, "Think of driving."], [18002, "You have a route, you hit unexpected traffic, and you reroute locally."], [22846, "You don't replan the whole trip; the destination stays the same."]]}, {"click": 6, "sents": [[27975, "A factory robot that has to re-attach a fallen car door, instead of blindly following its script, depends on exactly this loop."]]}]}, {"n": 67, "title": "Execution Monitoring", "sec": "11.5 Nondeterministic Domains", "dur": 54963, "clicks": [6536, 15908, 24158, 29220, 44131], "segs": [{"click": 0, "sents": [[500, "While a plan is running, how much should the agent check?"], [4409, "There are three levels."]]}, {"click": 1, "sents": [[6686, "Action monitoring checks only whether the next action's preconditions still hold."], [12174, "It catches trouble at the last possible moment."]]}, {"click": 2, "sents": [[16058, "Plan monitoring checks whether the entire remaining plan will still work."], [20935, "It catches trouble as early as possible."]]}, {"click": 3, "sents": [[24308, "Goal monitoring asks whether there's now a better goal to pursue."]]}, {"click": 4, "sents": [[29370, "Why does plan monitoring win?"], [31323, "Suppose there isn't enough red paint for both pieces."], [34893, "Action monitoring paints the chair first, then discovers the problem."], [39540, "Plan monitoring sees it up front, and never wastes the work."]]}, {"click": 5, "sents": [[44281, "Plan monitoring also notices good luck."], [47000, "If someone else paints the table while you work, it sees the goal is already met and stops early."]]}]}, {"n": 68, "title": "When Retrying Isn’t Enough", "sec": "11.5 Nondeterministic Domains", "dur": 59195, "clicks": [7163, 9900, 14884, 29063, 40683], "segs": [{"click": 0, "sents": [[500, "Online planning creates loops naturally."], [3556, "But sometimes retrying isn't the answer."]]}, {"click": 1, "sents": [[7313, "The agent paints the chair,"]]}, {"click": 2, "sents": [[10050, "and sees it's a patchy gray, with old paint showing through."]]}, {"click": 3, "sents": [[15034, "The chair still isn't fully painted, so the precondition for painting still holds, and the agent paints again."], [22374, "The loop comes from planning, acting, and replanning, not from anything written in the plan."]]}, {"click": 4, "sents": [[29213, "But if a can is empty, no amount of retrying will help."], [33298, "The agent has to update its model of the world."], [36789, "Every failed prediction is a chance to learn."]]}, {"click": 5, "sents": [[40833, "Real life mixes both."], [42360, "Cars come with spare tires and airbags, built-in plans for high-stakes events."], [48032, "But most drivers don't plan for a flat in advance; they replan when it happens."], [53777, "Plan ahead only where the stakes and the chances are real."]]}]}, {"n": 69, "title": "Why Northgate Never Uses Coercion", "sec": "11.5 Nondeterministic Domains", "dur": 51520, "clicks": [7581, 15203, 21624, 37161], "segs": [{"click": 0, "sents": [[500, "Could Northgate use the coercion trick?"], [3394, "No, and the reason is an important design lesson."]]}, {"click": 1, "sents": [[7731, "Coercion worked for paint because the goal was indifferent."], [11478, "Any color would do, as long as the pieces matched."]]}, {"click": 2, "sents": [[15353, "Maria's goal isn't just do some surgery."], [18488, "It's treat what she actually has."]]}, {"click": 3, "sents": [[21774, "If she has appendicitis, surgery helps."], [24820, "If she actually has gastroenteritis, an operate-regardless plan doesn't just fail; it harms her."], [32317, "No single action is right for every possible diagnosis."]]}, {"click": 4, "sents": [[37311, "So the general lesson: sensorless planning is only safe when the goal doesn't depend on the hidden fact."], [45042, "When it does, you must sense first, with contingent or online planning."]]}]}, {"n": 70, "title": "Contingent Care Plan at Northgate", "sec": "11.5 Nondeterministic Domains", "dur": 41589, "clicks": [5569, 13427, 17914, 25145, 29476], "segs": [{"click": 0, "sents": [[500, "Here's what a safe plan for Maria looks like: a contingent plan."]]}, {"click": 1, "sents": [[5719, "First, a percept schema: once a test is ordered for a patient, the planner learns the diagnosis."]]}, {"click": 2, "sents": [[13577, "The plan starts by ordering a CT scan for Maria."]]}, {"click": 3, "sents": [[18064, "If the diagnosis is appendicitis, run the four-step surgical plan from section 11.1."]]}, {"click": 4, "sents": [[25295, "Otherwise, prescribe antibiotics and discharge her."]]}, {"click": 5, "sents": [[29626, "Same shape as the paint plan: gather information cheaply first, then let the plan branch."], [36098, "The surgery only happens when the test result justifies it."]]}]}, {"n": 71, "title": "Check Yourself: Nondeterministic Domains", "sec": "11.5 Nondeterministic Domains", "dur": 50611, "clicks": [10454, 22961, 38812], "segs": [{"click": 0, "sents": [[500, "Let's check yourself on section 11.5."], [4642, "Pause the video and answer the three questions."]]}, {"click": 1, "sents": [[10604, "Number one: a belief state is the set of all worlds that might be real."], [15910, "Since the agent doesn't know which one it's in, an unlisted fact is unknown, not false."]]}, {"click": 2, "sents": [[23111, "Number two: for paint, any matching color satisfies the goal, so one plan works in every world."], [30767, "For a patient, the right action depends on the hidden diagnosis, so no single action is safe."]]}, {"click": 3, "sents": [[38962, "Number three: action monitoring checks the next step, plan monitoring checks the whole rest of the plan, and goal monitoring asks whether there's a better goal."]]}]}, {"n": 72, "title": "11.6 Time, Schedules & Resources", "sec": "11.6 Time, Schedules & Resources", "dur": 25106, "clicks": [], "segs": [{"click": 0, "sents": [[500, "Section 11.6: Time, Schedules, and Resources."], [3802, "Classical planning tells us what to do and in what order."], [7984, "It doesn't tell us when each action happens, how long it takes, or what happens when two actions need the same scarce resource."], [17302, "That's scheduling, and it's where planning meets factories, airlines, and operating rooms."]]}]}, {"n": 73, "title": "What Classical Planning Leaves Out", "sec": "11.6 Time, Schedules & Resources", "dur": 43631, "clicks": [4681, 14054, 24785, 34654], "segs": [{"click": 0, "sents": [[500, "Classical planning leaves two important things out."]]}, {"click": 1, "sents": [[4831, "The first is time."], [6154, "A plan tells you the order of the flights, but not when each one departs, or how long loading takes."]]}, {"click": 2, "sents": [[14204, "The second is shared resources."], [16474, "An airline has limited staff."], [18597, "Two actions that need the same scarce resource can't happen at the same time."]]}, {"click": 3, "sents": [[24935, "The usual approach: plan first, schedule later."], [28467, "Use the planning algorithms to decide what to do and roughly in what order."]]}, {"click": 4, "sents": [[34804, "Then add durations and resource limits in a second phase."], [38489, "That mirrors how real factories and logistics companies work."]]}]}, {"n": 74, "title": "A Job-Shop Scheduling Problem", "sec": "11.6 Time, Schedules & Resources", "dur": 52696, "clicks": [5961, 17659, 25281, 35150], "segs": [{"click": 0, "sents": [[500, "Here's the textbook's classic scheduling problem: assembling two cars."]]}, {"click": 1, "sents": [[6111, "Each car is a job with three steps in order: add the engine, add the wheels, then inspect."], [13181, "The curly less-than symbol means must come before."]]}, {"click": 2, "sents": [[17809, "The steps take different times."], [20044, "Car two's engine takes sixty minutes, twice as long as car one's."]]}, {"click": 3, "sents": [[25431, "And the resources are limited: one engine hoist, one wheel station, two inspectors, and five hundred lug nuts, which get used up."]]}, {"click": 4, "sents": [[35300, "Notice we write inspectors as the number two, not as two named people."], [40187, "This is called aggregation."], [42072, "Since it doesn't matter which inspector does the work, it keeps the problem small, and makes checks like not enough inspectors instant."]]}]}, {"n": 75, "title": "The Critical Path Method", "sec": "11.6 Time, Schedules & Resources", "dur": 61886, "clicks": [7084, 18939, 31838, 40166, 50505], "segs": [{"click": 0, "sents": [[500, "To schedule, we use the critical path method."], [3894, "It gives each action three numbers."]]}, {"click": 1, "sents": [[7234, "The earliest start time, ES."], [9514, "Start is at time zero."], [11305, "For any other action, it's the latest finish among everything that must come before it."]]}, {"click": 2, "sents": [[19089, "For example, adding wheels to car one can't start until its engine is in."], [24266, "The engine starts at zero and takes thirty minutes, so the earliest start for the wheels is thirty."]]}, {"click": 3, "sents": [[31988, "The latest start time, LS, is the latest an action can begin without delaying the whole project."]]}, {"click": 4, "sents": [[40316, "Slack is the difference."], [42030, "Zero slack means the action is on the critical path: delay it by even one minute, and everything finishes late."]]}, {"click": 5, "sents": [[50655, "Computing these numbers is fast, because it only involves simple inequalities."], [56126, "It's the resource limits, coming next, that make scheduling hard."]]}]}, {"n": 76, "title": "The Schedule Without Resource Limits", "sec": "11.6 Time, Schedules & Resources", "dur": 56635, "clicks": [5021, 14080, 26901, 34601, 46612], "segs": [{"click": 0, "sents": [[500, "Let's see the schedule if we ignore resource limits for a moment."]]}, {"click": 1, "sents": [[5171, "Car one: engine from zero to thirty, wheels from thirty to sixty, inspection from sixty to seventy."]]}, {"click": 2, "sents": [[14230, "Car two: engine from zero to sixty, wheels from sixty to seventy-five, inspection from seventy-five to eighty-five."], [23108, "Both cars are done at eighty-five minutes."]]}, {"click": 3, "sents": [[27051, "Car two's steps have zero slack."], [29486, "They're the critical path."], [31465, "Any delay there delays everything."]]}, {"click": 4, "sents": [[34751, "Car one has fifteen minutes of slack on every step."], [38356, "The numbers in brackets show earliest and latest start: the engine could start anywhere from zero to fifteen."]]}, {"click": 5, "sents": [[46762, "But look closely: both engines start at time zero, and there's only one engine hoist."], [52756, "This schedule isn't actually possible."]]}]}, {"n": 77, "title": "Resource Limits Make It NP-Hard", "sec": "11.6 Time, Schedules & Resources", "dur": 63113, "clicks": [5491, 15360, 22408, 33792, 45176], "segs": [{"click": 0, "sents": [[500, "Now let's add the resource limits, and see why everything gets harder."]]}, {"click": 1, "sents": [[5641, "If two actions share one resource, like our single engine hoist, they can't overlap."], [12168, "Either A finishes before B starts,"]]}, {"click": 2, "sents": [[15510, "or B finishes before A starts."], [18084, "We don't know which yet."], [20142, "That's an either-or."]]}, {"click": 3, "sents": [[22558, "Check the two engines, both starting at zero."], [26374, "Does engine one finish before engine two starts?"], [30444, "Thirty is not at most zero."], [32733, "False."]]}, {"click": 4, "sents": [[33942, "Does engine two finish before engine one starts?"], [38180, "Sixty is not at most zero."], [40476, "False."], [41006, "Neither holds, so one engine has to move."]]}, {"click": 5, "sents": [[45326, "Simple inequalities are easy."], [47707, "Either-or choices are not."], [49843, "Adding them makes scheduling with resources NP-hard."], [54113, "A 1963 challenge problem, with ten machines and ten jobs, went unsolved for twenty-three years."]]}]}, {"n": 78, "title": "The Schedule With Resource Limits", "sec": "11.6 Time, Schedules & Resources", "dur": 44096, "clicks": [4838, 9900, 15929, 23160, 31017], "segs": [{"click": 0, "sents": [[500, "Here's the best schedule once we respect the resource limits."]]}, {"click": 1, "sents": [[4988, "Engine one goes on the hoist first, from zero to thirty."]]}, {"click": 2, "sents": [[10050, "Engine two has to wait for the hoist, so it runs from thirty to ninety."]]}, {"click": 3, "sents": [[16079, "Car one moves on: wheels from thirty to sixty, inspection from sixty to seventy."]]}, {"click": 4, "sents": [[23310, "Car two follows: wheels from ninety to a hundred and five, inspection until a hundred and fifteen."]]}, {"click": 5, "sents": [[31167, "The finish is a hundred and fifteen minutes, thirty more than without limits."], [36608, "And notice: the two inspectors are never needed at once, so a manager could reassign one."]]}]}, {"n": 79, "title": "Heuristic Scheduling", "sec": "11.6 Time, Schedules & Resources", "dur": 57581, "clicks": [8051, 23510, 30819, 41158], "segs": [{"click": 0, "sents": [[500, "Since optimal scheduling is NP-hard, we usually use greedy heuristics, just as we did for planning."]]}, {"click": 1, "sents": [[8201, "The minimum-slack heuristic: at each step, schedule the ready action with the least slack first."], [14916, "It's like the minimum-remaining-values heuristic for CSPs from Chapter 5: tackle the most constrained choice first."]]}, {"click": 2, "sents": [[23660, "On the car problem, it gives a hundred and thirty minutes."], [27455, "The best possible is a hundred and fifteen."]]}, {"click": 3, "sents": [[30969, "Why?"], [31270, "Engine two has zero slack, so the heuristic gives it the hoist first."], [36466, "Then car one waits a full sixty minutes for its engine."]]}, {"click": 4, "sents": [[41308, "It works well in practice, but there's no guarantee."], [44920, "And if scheduling is proving too hard, sometimes the smarter move is to rethink the plan itself."], [51588, "That's why real systems increasingly combine planning and scheduling."]]}]}, {"n": 80, "title": "Hospital Edition: Two Patients", "sec": "11.6 Time, Schedules & Resources", "dur": 41881, "clicks": [4759, 12617, 20161, 33217], "segs": [{"click": 0, "sents": [[500, "Now the same math at Northgate, with two patients."]]}, {"click": 1, "sents": [[4909, "Maria's pathway: twenty minutes of prep, a forty-five-minute surgery, then a ten-minute recovery check."]]}, {"click": 2, "sents": [[12767, "David Chen's pathway: twenty minutes of prep, a sixty-minute surgery, and a ten-minute check."]]}, {"click": 3, "sents": [[20311, "There are two operating rooms and two nurses, so ignoring anything else, both finish by ninety minutes."], [27381, "David's pathway is the critical path, and Maria has fifteen minutes of slack."]]}, {"click": 4, "sents": [[33367, "But there's only one anesthesiologist on shift."], [36641, "And in this schedule, both surgeries run at the same time."]]}]}, {"n": 81, "title": "The Real Bottleneck: One Anesthesiologist", "sec": "11.6 Time, Schedules & Resources", "dur": 54963, "clicks": [5099, 12878, 18489, 30657, 40683], "segs": [{"click": 0, "sents": [[500, "Add the anesthesiologist constraint, and the schedule changes."]]}, {"click": 1, "sents": [[5249, "The two surgeries can't overlap: either Maria's finishes before David's starts, or the other way round."]]}, {"click": 2, "sents": [[13028, "Put Maria first: her surgery runs from twenty to sixty-five."]]}, {"click": 3, "sents": [[18639, "David's starts at sixty-five."], [20998, "Check: twenty plus forty-five is sixty-five, which is at most sixty-five."], [26935, "No overlap, with zero minutes to spare."]]}, {"click": 4, "sents": [[30807, "David finishes surgery at a hundred and twenty-five, and his check ends at a hundred and thirty-five."], [37259, "That's forty-five minutes longer than before."]]}, {"click": 5, "sents": [[40833, "Either order gives a hundred and thirty-five, since the two surgeries need a hundred and five minutes back to back."], [48231, "And whoever goes second has zero slack: one delayed prep pushes their whole day later."]]}]}, {"n": 82, "title": "What the Schedule Teaches", "sec": "11.6 Time, Schedules & Resources", "dur": 46061, "clicks": [3819, 10240, 20109, 36195], "segs": [{"click": 0, "sents": [[500, "What does this schedule teach the charge nurse?"]]}, {"click": 1, "sents": [[3969, "The two operating rooms were available the whole time."], [7520, "The rooms were never the problem."]]}, {"click": 2, "sents": [[10390, "The bottleneck was one human specialist that both surgeries needed."], [14941, "The lesson: find what's actually scarce before you start scheduling."]]}, {"click": 3, "sents": [[20259, "The minimum-slack heuristic would schedule David first, since his path has zero slack."], [26357, "Here, that still reaches a hundred and thirty-five, the best possible."], [31320, "But, as with the cars, greedy isn't guaranteed to be optimal."]]}, {"click": 4, "sents": [[36345, "This same critical-path-plus-resources math runs factory floors, airline crew schedules, and operating-room scheduling software."]]}]}, {"n": 83, "title": "Check Yourself: Scheduling", "sec": "11.6 Time, Schedules & Resources", "dur": 46432, "clicks": [10611, 19435, 32883], "segs": [{"click": 0, "sents": [[500, "Let's check yourself on section 11.6."], [4711, "Pause the video and answer the three questions."]]}, {"click": 1, "sents": [[10761, "Number one: zero slack means the action is on the critical path."], [15713, "Any delay to it delays the whole project."]]}, {"click": 2, "sents": [[19585, "Number two: a shared resource creates either-or choices, A before B or B before A."], [26508, "Those choices multiply, turning simple arithmetic into a hard search."]]}, {"click": 3, "sents": [[33033, "Number three: aggregation means counting interchangeable resources, like two inspectors, instead of naming each one."], [41357, "That avoids trying every way of assigning individuals."]]}]}, {"n": 84, "title": "11.7 Analysis of Planning Approaches", "sec": "11.7 Analysis of Planning Approaches", "dur": 17110, "clicks": [], "segs": [{"click": 0, "sents": [[500, "Section 11.7: Analysis of Planning Approaches."], [4130, "We close the chapter by stepping back."], [7128, "Planning is combinatorially hard in theory."], [10521, "So why does it work so well in practice?"], [13677, "And where does it lead next?"]]}]}, {"n": 85, "title": "Why Planning Is Hard", "sec": "11.7 Analysis of Planning Approaches", "dur": 42424, "clicks": [3819, 9848, 16426, 19816, 31357], "segs": [{"click": 0, "sents": [[500, "First, why is planning hard?"]]}, {"click": 1, "sents": [[3969, "Every fact in a domain can be true or false, independently of the others."]]}, {"click": 2, "sents": [[9998, "So ten facts give up to two to the ten, about a thousand, possible states."]]}, {"click": 3, "sents": [[16576, "Thirty facts give about a billion."]]}, {"click": 4, "sents": [[19966, "Three hundred facts give more states than there are atoms in the universe."], [24828, "And remember the large Air Cargo problem, with roughly two thousand to the forty-one nodes."]]}, {"click": 5, "sents": [[31507, "Whether we think of a planner as searching for a plan, or as proving that one exists, combinatorial explosion is the default, not the exception."]]}]}, {"n": 86, "title": "Why Planners Still Win: Structure", "sec": "11.7 Analysis of Planning Approaches", "dur": 64707, "clicks": [8678, 19330, 28390, 37135, 50844], "segs": [{"click": 0, "sents": [[500, "So why does planning work so well in practice?"], [3842, "Because every technique in this chapter exploits structure."]]}, {"click": 1, "sents": [[8828, "Look back at the toolkit: a factored representation, goal-directed search, relaxed heuristics, abstraction and decomposition, and hierarchy."]]}, {"click": 2, "sents": [[19480, "Each one is the same weapon aimed differently: exploit the structure of the problem, rather than relying on raw computing power."]]}, {"click": 3, "sents": [[28540, "The biggest lever is independent subproblems."], [31892, "When a problem fully decomposes, we get an exponential speedup."]]}, {"click": 4, "sents": [[37285, "Negative interactions, where one action undoes another's progress, break that."], [43219, "SAT planners encode those interactions in logic; forward search handles them with heuristics."]]}, {"click": 5, "sents": [[50994, "And modern systems often use portfolio planning: run several planners, in sequence or in parallel, and keep the best answer."], [59963, "Fast Downward Stone Soup is a well-known example."]]}]}, {"n": 87, "title": "Where Planning Leads Next", "sec": "11.7 Analysis of Planning Approaches", "dur": 48386, "clicks": [7737, 17110, 27292, 38598], "segs": [{"click": 0, "sents": [[500, "Chapter 11 isn't the last word on planning."], [3434, "It's the foundation for what comes later in the course."]]}, {"click": 1, "sents": [[7887, "Here, actions had known effects."], [10410, "In Chapter 16, Markov decision processes attach probabilities to the outcomes."]]}, {"click": 2, "sents": [[17260, "Here, we handled partial observability with belief states."], [21731, "In Chapter 16, partially observable MDPs make that probabilistic."]]}, {"click": 3, "sents": [[27442, "And here, the agent was given a correct model of the world."], [31758, "In Chapter 23, reinforcement learning lets the agent learn how to act from experience."]]}, {"click": 4, "sents": [[38748, "Factored states, action schemas, relaxation heuristics, and hierarchy all reappear, transformed, in those chapters."]]}]}, {"n": 88, "title": "Same Toolkit, Two Worlds", "sec": "11.7 Analysis of Planning Approaches", "dur": 58249, "clicks": [5491, 14707, 23296, 29638, 41022, 48070], "segs": [{"click": 0, "sents": [[500, "Let's check every big idea against both domains, one last time."]]}, {"click": 1, "sents": [[5641, "The RESULT rule: Fly moves a plane between airports; transfer to OR moves a patient into surgery."]]}, {"click": 2, "sents": [[14857, "Relaxation: ignore Load's delete list, or ignore transfer to OR's delete list."], [21850, "Same code."]]}, {"click": 3, "sents": [[23446, "High-level actions: go from home to the airport, or admit Maria."]]}, {"click": 4, "sents": [[29788, "Belief states: here's the one real difference."], [33249, "Coercion works for paint, but a diagnosis needs sensing, because the right action depends on it."]]}, {"click": 5, "sents": [[41172, "Scheduling: one engine hoist, one anesthesiologist."], [45432, "The same bottleneck math."]]}, {"click": 6, "sents": [[48220, "That's what domain-independent means: the same algorithms and the same code, pointed at cargo one moment and patient care the next."]]}]}, {"n": 89, "title": "Check Yourself: Analysis", "sec": "11.7 Analysis of Planning Approaches", "dur": 44896, "clicks": [10036, 27977], "segs": [{"click": 0, "sents": [[500, "Let's check yourself on section 11.7."], [4555, "Pause the video and answer the two questions."]]}, {"click": 1, "sents": [[10186, "Number one: each fact can be true or false independently, so n facts give up to two to the n states."], [18023, "Planners avoid brute force with heuristics, abstraction, decomposition, and hierarchy."], [24762, "Any two of those is a good answer."]]}, {"click": 2, "sents": [[28127, "Number two: one example is the RESULT rule."], [31346, "Fly and transfer to OR use exactly the same equation, because the planner only reads action schemas, whatever the domain."], [40403, "Any concept from the comparison table works."]]}]}, {"n": 90, "title": "Wrap-Up", "sec": "Wrap-Up", "dur": 9430, "clicks": [], "segs": [{"click": 0, "sents": [[500, "Let's wrap up Chapter 11."], [2105, "We'll recap the chapter in three ideas, and finish with three questions for you to think about."]]}]}, {"n": 91, "title": "Chapter 11 Recap", "sec": "Wrap-Up", "dur": 46766, "clicks": [4524, 17502, 25438, 32668], "segs": [{"click": 0, "sents": [[500, "Here's what you should be able to explain after this chapter."]]}, {"click": 1, "sents": [[4674, "Representation: a planning problem is an initial state, actions, and a goal."], [10434, "States are sets of facts, and actions have preconditions, add lists, and delete lists."]]}, {"click": 2, "sents": [[17652, "Algorithms: forward search, backward search, SAT planning, and partial-order plans."]]}, {"click": 3, "sents": [[25588, "Scaling: heuristics from relaxed problems, abstraction, decomposition, and hierarchy."]]}, {"click": 4, "sents": [[32818, "And beyond classical planning: belief states, contingent and online plans, and scheduling with time and resources."], [40548, "If you can explain each of these in plain English, you've got the chapter."]]}]}, {"n": 92, "title": "The One Idea to Take With You", "sec": "Wrap-Up", "dur": 51102, "clicks": [9566, 18547, 28572, 38520], "segs": [{"click": 0, "sents": [[500, "If you remember just one idea from this chapter, make it this: planning is representation, plus search, plus structure."]]}, {"click": 1, "sents": [[9716, "Representation: factored states and action schemas let a computer reason about a domain, instead of searching it blindly."]]}, {"click": 2, "sents": [[18697, "Search: forward, backward, and logic-based search are all possible because the representation is a description, not a program."]]}, {"click": 3, "sents": [[28722, "Structure: heuristics, abstraction, decomposition, and hierarchy are what defeat exponential state spaces in practice."]]}, {"click": 4, "sents": [[38670, "Real systems are built on exactly these ideas: NASA's Remote Agent, Hitachi's factory scheduler, Mars rover mission planning, and modern logistics."]]}]}, {"n": 93, "title": "Three Questions to Close", "sec": "Wrap-Up", "dur": 60689, "clicks": [6928, 20715, 34972, 50588], "segs": [{"click": 0, "sents": [[500, "To close, here are three questions."], [3104, "Pause the video and write down your answers."]]}, {"click": 1, "sents": [[7078, "Question one connects to section 11.1."], [9766, "The closed-world assumption keeps states short, and works when the records are complete."], [15991, "It becomes unrealistic when facts can genuinely be unknown."]]}, {"click": 2, "sents": [[20865, "Question two connects to section 11.3."], [23605, "Ignoring delete lists keeps the preconditions, so the relaxed plan still does the real work of making actions legal."], [31971, "That's why it's a closer estimate."]]}, {"click": 3, "sents": [[35122, "Question three connects to section 11.5."], [38182, "With belief states, the planner tracks every possible world, so an unlisted fact means unknown, not false."], [46290, "That's why the closed-world assumption has to go."]]}, {"click": 4, "sents": [[50738, "If you can answer all three clearly, you've got the throughline of Chapter 11."], [55649, "Thank you for watching, and I'll see you in the next chapter."]]}]}]};
